import java.util.*;

public class Main {
    static class Edge {
        int to, rev, cap, cost;
        public Edge(int to, int rev, int cap, int cost) {
            this.to = to;
            this.rev = rev;
            this.cap = cap;
            this.cost = cost;
        }
    }

    static class MCFGraphIntCost {
        int n;
        List<int[]> pos;
        List<List<Edge>> g;
        int[] dist, pv, pe, dual;
        boolean[] vis;

        public MCFGraphIntCost(int n) {
            this.n = n;
            this.pos = new ArrayList<>();
            this.g = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                g.add(new ArrayList<>());
            }
        }

        public int addEdge(int from, int to, int cap, int cost) {
            int m = pos.size();
            pos.add(new int[]{from, g.get(from).size()});
            g.get(from).add(new Edge(to, g.get(to).size(), cap, cost));
            g.get(to).add(new Edge(from, g.get(from).size() - 1, 0, -cost));
            return m;
        }

        public class EdgeWrapper {
            int from, to, cap, flow, cost;
            public EdgeWrapper(int from, int to, int cap, int flow, int cost) {
                this.from = from;
                this.to = to;
                this.cap = cap;
                this.flow = flow;
                this.cost = cost;
            }
        }

        public EdgeWrapper getEdge(int i) {
            int[] eInfo = pos.get(i);
            Edge e = g.get(eInfo[0]).get(eInfo[1]);
            Edge re = g.get(e.to).get(e.rev);
            return new EdgeWrapper(eInfo[0], e.to, e.cap + re.cap, re.cap, e.cost);
        }

        public List<EdgeWrapper> edges() {
            List<EdgeWrapper> ret = new ArrayList<>();
            for (int i = 0; i < pos.size(); i++) {
                int[] eInfo = pos.get(i);
                Edge e = g.get(eInfo[0]).get(eInfo[1]);
                Edge re = g.get(e.to).get(e.rev);
                ret.add(new EdgeWrapper(eInfo[0], e.to, e.cap + re.cap, re.cap, e.cost));
            }
            return ret;
        }

        private boolean dualRef(int s, int t) {
            dist = new int[n];
            pv = new int[n];
            pe = new int[n];
            vis = new boolean[n];
            Arrays.fill(dist, Integer.MAX_VALUE);
            Arrays.fill(pv, -1);
            Arrays.fill(pe, -1);
            Arrays.fill(vis, false);
            PriorityQueue<long[]> que = new PriorityQueue<>(Comparator.comparingLong(a -> a[0]));
            dist[s] = 0;
            que.offer(new long[]{0L, s});
            while (!que.isEmpty()) {
                long[] current = que.poll();
                int v = (int) current[1];
                if (vis[v]) continue;
                vis[v] = true;
                if (v == t) break;
                for (int i = 0; i < g.get(v).size(); i++) {
                    Edge e = g.get(v).get(i);
                    if (vis[e.to] || e.cap == 0) continue;
                    int cost = e.cost - dual[e.to] + dual[v];
                    if (dist[e.to] > dist[v] + cost) {
                        dist[e.to] = dist[v] + cost;
                        pv[e.to] = v;
                        pe[e.to] = i;
                        long newDist = ((long) dist[e.to] << 32) + e.to;
                        que.offer(new long[]{newDist, e.to});
                    }
                }
            }
            if (!vis[t]) return false;
            for (int v = 0; v < n; v++) {
                if (!vis[v]) continue;
                dual[v] -= dist[t] - dist[v];
            }
            return true;
        }

        public List<long[]> slope(int s, int t, long flowLimit) {
            dual = new int[n];
            dist = new int[n];
            pv = new int[n];
            pe = new int[n];
            vis = new boolean[n];

            Arrays.fill(dual, 0);
            Arrays.fill(dist, Integer.MAX_VALUE);
            Arrays.fill(pv, -1);
            Arrays.fill(pe, -1);
            Arrays.fill(vis, false);

            long flow = 0;
            long cost = 0;
            long prevCost = -1;
            List<long[]> result = new ArrayList<>();
            result.add(new long[]{flow, cost});
            while (flow < flowLimit) {
                if (!dualRef(s, t))
                    break;
                long c = flowLimit - flow;
                int v = t;
                while (v != s) {
                    c = Math.min(c, g.get(pv[v]).get(pe[v]).cap);
                    v = pv[v];
                }
                v = t;
                while (v != s) {
                    Edge e = g.get(pv[v]).get(pe[v]);
                    e.cap -= c;
                    g.get(v).get(e.rev).cap += c;
                    v = pv[v];
                }
                long d = -dual[s];
                flow += c;
                cost += c * d;
                if (prevCost == d) {
                    if (!result.isEmpty()) result.remove(result.size() -1);
                }
                result.add(new long[]{flow, cost});
                prevCost = cost;
            }
            return result;
        }

        public long[] flow(int s, int t, long flowLimit) {
            List<long[]> res = slope(s, t, flowLimit);
            return res.get(res.size() - 1);
        }
    }

    static final int INF = 1000000000;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int a1 = sc.nextInt();
        int a2 = sc.nextInt();
        int a3 = sc.nextInt();
        int b1 = sc.nextInt();
        int b2 = sc.nextInt();
        int b3 = sc.nextInt();

        MCFGraphIntCost g = new MCFGraphIntCost(8);
        g.addEdge(0,1,a1,0);
        g.addEdge(0,2,a2,0);
        g.addEdge(0,3,a3,0);
        g.addEdge(4,7,b1,0);
        g.addEdge(5,7,b2,0);
        g.addEdge(6,7,b3,0);
        for (int i=1; i<=3; i++){
            for (int j=4; j<=6; j++) {
                int cost = ((j - i) % 3 == 1) ? 1 : 0;
                g.addEdge(i,j,INF,cost);
            }
        }
        long[] flowRes = g.flow(0,7, Long.MAX_VALUE);
        long ans1 = flowRes[1];

        long ans2 = Math.min(a1, b2) + Math.min(a2, b3) + Math.min(a3, b1);
        System.out.println(ans1 + " " + ans2);
    }
}
